(8)*/    :B3 , :B2 , :B1 , I.BRA_CODE, I.REF_TYPE, I.REF_YEAR, I.REF_NUM,    I.BRA_CODE || I.CUS_NUM CUS_NUM, I.CUR_CODE, I.LED_CODE,    I.SUB_ACCT_CODE, I.INS_SEQ, I.MAT_DATE, I.INS_AMT, I.INS_BAL,    I.PRV_INS_BAL, I.INS_INT, I.BAT_FLAG, I.INS_STA, I.DATE_STA_CHA,    I.MEM_FLAG, I.MEM_ISS_DATE, I.TRA_DATE, I.TRA_SEQ1, I.TRA_SEQ2,    I.UPD_TIME, LPAD (I.BRA_CODE, 4, ''0'') || LPAD (I.CUS_NUM, 7, ''0'') ||    LPAD (I.CUR_CODE, 3, ''0'') || LPAD (I.LED_CODE, 4, ''0'') || LPAD    (I.SUB_ACCT_CODE, 3, ''0'') ACCOUNT_NUMBER, I.BRA_CODE || LPAD    (I.REF_TYPE, 2, ''0'') || LPAD (I.REF_YEAR, 2, ''0'') || LPAD (I.REF_NUM,    6, ''0'') LOAN_KEY, I.DAILY_INT, I.RETURN_INT_AMT, I.REM_PRINCIPLE,    I.ACCU_INS_INT, I.COMP_INT_AMT, I.TOT_ACCU_INT, I.DAYS_PER,    I.DEP_INT_PER_AMT, I.DEP_INT_AMT, I.SUBS_INT_AMT, I.SUBS_INT_BAL,    I.COM_AMT, I.COM_BAL, I.VAT_AMT, I.VAT_BAL, I.TOT_PAY_AMT,    I.TOT_PAY_BAL, I.ORG_INS_BAL, I.SET_BAL, I.SENT_TO_ARR_BAL,    I.RESCH_DATE, 0, 0, I.NO_OF_DAYS, I.DAILY_COM, I.COM_PER,    I.COM_AMT_EACH_PER, I.INS_BAL * X.SPOT_RATE FROM LOAN_PAY@BANKBI I ,    BI_ODS.LOAN_TAB T, BI_ODS.CURRENCY X WHERE T.DAY_DATE = :B3 AND    T.COUNTRY_CODE =:B2 AND T.INST_CODE =:B1 AND T.BRA_CODE = I.BRA_CODE    AND T.LED_CODE = I.LED_CODE AND T.CUS_NUM =I.BRA_CODE || I.CUS_NUM    AND T.REF_TYPE=I.REF_TYPE AND T.REF_YEAR=I.REF_YEAR AND T.REF_NUM =    I.REF_NUM AND T.CUR_CODE=I.CUR_CODE AND    T.SUB_ACCT_CODE=I.SUB_ACCT_CODE AND I.CUR_CODE = X.CUR_CODE AND    X.DAY_DATE = :B3 AND X.COUNTRY_CODE = DECODE (:B2 , 999999,    X.COUNTRY_CODE, :B2 ) AND X.INST_CODE = DECODE (:B1 , 999999,    X.INST_CODE, :B1 ))',
